// A blank id is an unauthenticated request. The policy already refuses
// one, so this branch is the belt to that braces — and it answers
// `false` rather than an error, because "not signed up" is true.
const id = Inputs.userId === undefined || Inputs.userId === null ? '' : String(Inputs.userId);
if (id.length === 0) {
  Outputs.notify = false;
  Outputs.nobody();
  return;
}
Outputs.userId = id;
Outputs.ok();

function tpl002Rows(raw) {
  const list = raw && raw.items ? raw.items : (Array.isArray(raw) ? raw : []);
  const out = [];
  for (let i = 0; i < list.length; i++) {
    const m = list[i];
    const data = m && m.data ? m.data : m;
    const id = m && typeof m.getId === "function" ? m.getId() : (data && (data.id || data.objectId));
    out.push({ id: id, data: data || {} });
  }
  return out;
}
// `rows` is the only output that separates "matched nothing" from "no
// query has run yet"; `isEmpty` is true for both.
if (Inputs.rows === undefined) return;
const rows = tpl002Rows(Inputs.rows);
Outputs.notify = rows.length > 0 && rows[0].data['notifyByEmail'] === true;
Outputs.answered();
